    val stories = listOf(
        StorySeries(
            id = "the_rooftop_seed_exchange",
            title = "The Rooftop Seed Exchange",
            tagline = "Young neighbours build a careful seed-sharing project and discover the value of patience and local knowledge.",
            parts = listOf(
                StoryPart(1, "The Paper Envelope", listOf("Mariam found a small paper envelope of seeds in the community centre's gardening cupboard. A note said they had been collected for a future planting day, but it did not identify the plant.", "She showed the envelope to the garden coordinator, who explained that unidentified seeds should not be planted or distributed until their source and type were checked.", "The group decided to start a seed exchange using clearly labelled packets from reliable suppliers and approved local donations.")),
                StoryPart(2, "A Table of Labels", listOf("The students prepared a table with envelopes, labels, and a catalogue sheet. Each packet needed the plant name, source, date received, and any growing notes supplied with it.", "They avoided promising that every seed would grow. The coordinator explained that age, storage, weather, and local conditions could affect results.", "Mariam wrote a sign reminding visitors to ask the garden team before planting unfamiliar seeds.")),
                StoryPart(3, "The First Visitors", listOf("Families arrived with labelled packets of herbs and flowers. The volunteers checked each one and recorded how many packets were available.", "A visitor brought a packet with a handwritten name that no one could read confidently. Rather than guessing, the coordinator set it aside for identification.", "The students learned that careful labelling was part of caring for a garden, not just organising a cupboard.")),
                StoryPart(4, "A Rooftop Question", listOf("The group planned a small rooftop growing area, but first the building manager reviewed weight limits, access rules, and safe placement for containers.", "The students helped with labels and watering records, not moving heavy planters or making changes to the roof.", "They chose lightweight containers already approved for the space and waited for the coordinator to prepare them.")),
                StoryPart(5, "The Slow Germination", listOf("Some seedlings appeared quickly, while others took longer. One student worried that the slower packets had failed.", "The coordinator explained that different plants germinate at different rates and that packet instructions should guide expectations.", "Mariam added observation dates to the garden log so the group could compare results without rushing to conclusions.")),
                StoryPart(6, "A Mix-Up", listOf("Two packets had been placed in the wrong row of the catalogue. The volunteers noticed because the source labels did not match the recorded notes.", "They paused distribution, checked the original envelopes, and corrected the records before anyone took the packets home.", "The group added a second-person check for every new entry.")),
                StoryPart(7, "Sharing the Harvest Notes", listOf("The first herbs grew well enough for the coordinator to demonstrate how leaves could be harvested responsibly without damaging the plants.", "The students wrote down the approved guidance and added a note that each plant had different needs. They did not turn one example into a rule for every species.", "Visitors began leaving their own growing observations, clearly marked with dates and general neighbourhood locations.")),
                StoryPart(8, "The Dry Week", listOf("A hot, dry week arrived while the coordinator was away. The students followed the written watering plan and contacted the building manager when a container needed attention beyond their role.", "They did not improvise changes to the rooftop system. An adult volunteer reviewed the plants and adjusted the schedule according to approved guidance.", "Mariam learned that being responsible sometimes meant asking for help rather than trying to solve everything alone.")),
                StoryPart(9, "A Packet Returned", listOf("A family returned several unopened packets because their garden plans had changed. The coordinator checked the labels and storage condition before adding them back to the exchange.", "The students updated the catalogue and thanked the family for returning the packets rather than leaving them unused at home.", "The exchange now had enough clearly identified varieties for another planting season.")),
                StoryPart(10, "Seeds for Next Season", listOf("At the end of the season, the group reviewed its records and displayed photographs of the plants that had grown successfully.", "The unidentified envelope remained safely set aside until its contents could be identified. The coordinator said it was better to leave one mystery unresolved than distribute something uncertain.", "Mariam placed a fresh stack of blank labels beside the catalogue. The next season would begin with good records, shared knowledge, and room for new discoveries."))
